const TOKEN = '__GITOPS_TOKEN__';
const PERMITIDOS = '__GITOPS_REPOS__'.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const it = $input.first().json;
const h = it.headers || {};
const b = it.body || {};
if (!TOKEN || h['x-heimdall-token'] !== TOKEN) throw new Error('Token do webhook inválido.');
const repo = String(b.repo || '');
const branch = String(b.branch || '');
const sha = String(b.sha || '');
if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo)) throw new Error('Nome de repositório inválido.');
if (!/^[0-9a-f]{40}$/.test(sha)) throw new Error('SHA inválido.');
if (!/^[A-Za-z0-9._\/-]+$/.test(branch)) throw new Error('Nome de branch inválido.');
if (!PERMITIDOS.includes(repo.toLowerCase())) throw new Error('Repositório não autorizado: ' + repo);
if (branch.startsWith('fix/refactor-auto-')) return [];
return [{ json: { repo, branch, sha } }];

const nomes = $input.all().map(i => i.json && i.json.name).filter(Boolean);
const v = $('Validar').first().json;
const lista = ['package.json', 'requirements.txt', 'pyproject.toml', 'go.mod', 'Cargo.toml', 'pom.xml', 'build.gradle', 'Gemfile', 'composer.json'];
const m = lista.find(x => nomes.includes(x));
// Sem manifesto, busca os metadados do repositório (que trazem a linguagem principal).
const url = m
  ? 'https://api.github.com/repos/' + v.repo + '/contents/' + m + '?ref=' + v.sha
  : 'https://api.github.com/repos/' + v.repo;
return [{ json: { nomes, manifesto: m || '', url } }];

const c = $input.first().json;
const v = $('Validar').first().json;
const msg = String((c.commit && c.commit.message) || '');
const rotulo = 'Commit ' + v.sha.slice(0, 7) + ' (' + v.repo + ', branch ' + v.branch + '): ';
const vazio = (titulo, motivo) => [{ json: { vazio: true, titulo, motivo: rotulo + motivo } }];
if (/\[(skip|auto)[- ]?(ai|refactor|heimdall)\]/i.test(msg) || /^refactor\(auto\)/i.test(msg)) return vazio('GitOps: commit ignorado', 'a mensagem pede para não analisar, então não analisei.');
const EXT = { py: 'Python', js: 'JavaScript', mjs: 'JavaScript', ts: 'TypeScript', jsx: 'JavaScript (React)', tsx: 'TypeScript (React)',
  go: 'Go', rs: 'Rust', java: 'Java', kt: 'Kotlin', rb: 'Ruby', php: 'PHP', cs: 'C#', c: 'C', cpp: 'C++', sh: 'Shell',
  sql: 'SQL', scala: 'Scala', swift: 'Swift', tf: 'Terraform' };
const IGN = /(^|\/)(node_modules|vendor|dist|build|\.venv|venv|__pycache__|migrations)\//;
const arquivos = (c.files || [])
  .filter(f => f.filename && f.status !== 'removed' && f.patch && !IGN.test(f.filename) && !/\.min\./.test(f.filename)
    && EXT[String(f.filename.split('.').pop()).toLowerCase()])
  .sort((a, b) => (b.changes || 0) - (a.changes || 0))
  .slice(0, 4);
if (arquivos.length === 0) return vazio('GitOps: sem código para analisar', 'nenhum arquivo de código alterado (' + (c.files || []).length + ' arquivo(s) no commit, só documentação, dados ou tipos que não analiso).');
return arquivos.map(f => ({ json: {
  vazio: false,
  path: f.filename,
  linguagem: EXT[String(f.filename.split('.').pop()).toLowerCase()],
  patch: String(f.patch).slice(0, 60000),
  url: 'https://api.github.com/repos/' + v.repo + '/contents/' + f.filename.split('/').map(encodeURIComponent).join('/') + '?ref=' + v.sha,
} }));

const sel = $('Selecionar arquivos').all();
const v = $('Validar').first().json;
const man = $('Ler manifesto').first().json || {};
const nomes = $('Escolher manifesto').first().json.nomes || [];
const commit = $('Commit no GitHub').first().json || {};
let manifesto = '';
if (man.content && man.encoding === 'base64') manifesto = Buffer.from(man.content, 'base64').toString('utf8').slice(0, 1500);
const contexto = 'Repositório: ' + v.repo + ' | branch: ' + v.branch
  + '\nLinguagem principal segundo o GitHub: ' + (man.language || 'não informada')
  + '\nArquivos na raiz: ' + nomes.slice(0, 40).join(', ')
  + (manifesto ? '\nManifesto de dependências (' + $('Escolher manifesto').first().json.manifesto + '):\n' + manifesto : '')
  + '\nMensagem do commit: ' + String((commit.commit && commit.commit.message) || '').slice(0, 300);
const SYS = `Você é um engenheiro de software sênior fazendo a revisão de um commit. Você recebe um TRECHO de um arquivo maior (as linhas que o commit mexeu e o código ao redor) e o diff dessa parte. Analise o TRECHO sob três óticas rigorosas:
1. Segurança: injeção de comandos ou SQL, segredos no código, validação de entrada, desserialização insegura, criptografia fraca, permissões excessivas.
2. Performance e eficiência: complexidade desnecessária, consultas ou I/O repetidos, alocações inúteis, estruturas de dados inadequadas.
3. Boas práticas de arquitetura: responsabilidade única, acoplamento, tratamento de erros, legibilidade, testabilidade.
Seja conservador: proponha apenas melhorias claras e seguras. Nunca remova nem reescreva textos que o programa mostra ou pergunta ao usuário (prompts, mensagens de aviso e de erro, saídas de echo ou print): o dono usa leitor de tela e depende deles. Não mude o comportamento visível, a API pública, nomes públicos nem as dependências, e não faça mudanças só de estilo. Você só vê esta parte do arquivo: não invente problemas sobre nomes, funções ou importações que não aparecem no trecho, e não mude as linhas de assinatura que outras partes do arquivo possam usar. Concentre-se nas linhas alteradas no commit (o diff), mas pode corrigir problemas no mesmo trecho.
Responda em português do Brasil, EXATAMENTE neste formato, sem nenhum texto fora dele.
Para cada problema encontrado:
ACHADO
CATEGORIA: seguranca ou performance ou arquitetura
SEVERIDADE: alta ou media ou baixa
LINHAS: faixa aproximada de linhas
PROBLEMA: o que está errado, em uma ou duas frases
POR_QUE_IMPORTA: explicação didática, como para um colega júnior, com o risco concreto
CORRECAO: o que foi mudado e por que a nova forma é melhor
FIM_ACHADO
Depois dos achados, uma linha: VEREDITO: REFATORAR ou VEREDITO: OK
Se o veredito for REFATORAR, inclua o TRECHO INTEIRO já corrigido (somente ele, começando e terminando nas mesmas linhas lógicas do original) entre estas marcas, sem cercas de markdown:
<<<ARQUIVO>>>
(código do trecho completo)
<<<FIM_ARQUIVO>>>
Se não houver melhoria clara, escreva somente VEREDITO: OK, sem achados.`;
const MAX = 5000;        // caracteres por trecho (protege a memória do Mac)
const MAX_TRECHOS = 8;   // trechos por commit (limita o tempo da análise)
const ARQ_MAX = 80000;   // arquivos maiores que isso não são analisados
const hunks = patch => {
  const idx = [];
  const re = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@.*$/gm;
  let m;
  while ((m = re.exec(patch))) idx.push({ pos: m.index, ini: +m[1], n: m[2] === undefined ? 1 : +m[2] });
  return idx.map((h, k) => ({ ini: h.ini, fim: h.ini + Math.max(h.n, 1) - 1, texto: patch.slice(h.pos, k + 1 < idx.length ? idx[k + 1].pos : patch.length) }));
};
// Divide em blocos que começam em linhas sem recuo (início de função, classe ou comando) e junta blocos até MAX.
const cortar = codigo => {
  const linhas = codigo.split('\n');
  const fronteira = (l, i) => i === 0 || (/^\S/.test(l) && !/^[})\]]/.test(l) && !/^(else|elif|except|finally|catch|end|fi|done|esac)\b/.test(l) && !/^@/.test(linhas[i - 1] || '') && !/\\$/.test(linhas[i - 1] || ''));
  const ini = [];
  linhas.forEach((l, i) => { if (fronteira(l, i)) ini.push(i); });
  const blocos = ini.map((a, k) => ({ a, b: (k + 1 < ini.length ? ini[k + 1] : linhas.length) - 1 }));
  const trechos = [];
  let cur = null;
  const len = b => linhas.slice(b.a, b.b + 1).join('\n').length + 1;
  blocos.forEach(b => {
    const tam = len(b);
    if (tam > MAX) { if (cur) trechos.push(cur); cur = null; trechos.push({ a: b.a, b: b.b, grande: true }); return; }
    if (cur && cur.tam + tam <= MAX) { cur.b = b.b; cur.tam += tam; }
    else { if (cur) trechos.push(cur); cur = { a: b.a, b: b.b, tam }; }
  });
  if (cur) trechos.push(cur);
  return trechos.map(t => ({ a: t.a, b: t.b, grande: !!t.grande, texto: linhas.slice(t.a, t.b + 1).join('\n') }));
};
const out = [];
const meta = { grandes: 0, limite: 0, arquivosGrandes: 0 };
$input.all().forEach((it, i) => {
  const j = it.json || {};
  const s = (sel[i] || { json: {} }).json;
  if (j.encoding !== 'base64' || !j.content) return;
  const codigo = Buffer.from(j.content, 'base64').toString('utf8');
  if (codigo.length < 30) return;
  if (codigo.length > ARQ_MAX) { meta.arquivosGrandes++; return; }
  const hs = hunks(s.patch);
  const total = codigo.split('\n').length;
  cortar(codigo).forEach(t => {
    const a = t.a + 1, b = t.b + 1;
    const tocados = hs.filter(h => h.ini <= b && h.fim >= a);
    if (tocados.length === 0) return;
    if (t.grande) { meta.grandes++; return; }
    if (out.length >= MAX_TRECHOS) { meta.limite++; return; }
    const diff = tocados.map(h => h.texto).join('\n').slice(0, 2500);
    const user = contexto + '\n\nARQUIVO: ' + s.path + ' (' + s.linguagem + ')\nTRECHO: linhas ' + a + ' a ' + b + ' de ' + total
      + '\n\nDIFF DO COMMIT (só as partes deste trecho):\n' + diff
      + '\n\nTRECHO ATUAL:\n<<<ATUAL>>>\n' + t.texto + '\n<<<FIM_ATUAL>>>';
    out.push({ json: { vazio: false, path: s.path, shaBlob: j.sha, original: codigo, ini: t.a, fim: t.b, texto: t.texto, meta, req: {
      model: '__MODELO_CODIGO__', temperature: 0.1, max_tokens: 3500, stream: false,
      messages: [ { role: 'system', content: SYS }, { role: 'user', content: user } ] } } });
  });
});
if (out.length === 0) return [{ json: { vazio: true, titulo: 'GitOps: nada para analisar',
  motivo: 'Commit ' + v.sha.slice(0, 7) + ' (' + v.repo + ', branch ' + v.branch + '): não havia trecho analisável. Arquivos vazios ou ilegíveis no GitHub: possível; arquivos com mais de ' + (ARQ_MAX / 1000) + ' mil caracteres: ' + meta.arquivosGrandes + '; trechos alterados grandes demais (mais de ' + (MAX / 1000) + ' mil caracteres sem ponto de divisão): ' + meta.grandes + '.' } }];
return out;

const base = $('Montar análise').all();
const v = $('Validar').first().json;
const CAT = { seguranca: 'Segurança', performance: 'Performance e eficiência', arquitetura: 'Arquitetura e boas práticas' };
const SEV = { alta: 'ALTA', media: 'MÉDIA', baixa: 'BAIXA' };
const sem = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
function parseAchados(txt) {
  const out = [];
  const re = /\*{0,2}ACHADO\*{0,2}[ \t]*\r?\n([\s\S]*?)\*{0,2}FIM[_ ]ACHADO\*{0,2}/g;
  let m;
  while ((m = re.exec(txt))) {
    const campos = {};
    let atual = null;
    m[1].split(/\r?\n/).forEach(l => {
      const k = /^\s*[-*#]*\s*\**(CATEGORIA|SEVERIDADE|LINHAS|PROBLEMA|POR_QUE_IMPORTA|CORRECAO)\**\s*:\**\s*(.*)$/.exec(l);
      if (k) { atual = k[1]; campos[atual] = k[2]; } else if (atual) { campos[atual] += ' ' + l.trim(); }
    });
    if (campos.PROBLEMA) out.push(campos);
  }
  return out;
}
const balanceado = t => [['(', ')'], ['[', ']'], ['{', '}']].every(p => t.split(p[0]).length === t.split(p[1]).length);
const arquivos = [];
const secoes = [];
const contagem = { seguranca: 0, performance: 0, arquitetura: 0 };
const tally = { analisados: 0, ok: 0, descartados: 0 };
const descartes = [];
const rej = (path, motivo) => { tally.descartados++; descartes.push(path + ': ' + motivo); };
const porArquivo = {};
const meta = (base[0] && base[0].json && base[0].json.meta) || {};
const notaOmitidos = ((meta.grandes || 0) + (meta.limite || 0) + (meta.arquivosGrandes || 0))
  ? ' Não analisado: ' + (meta.grandes || 0) + ' trecho(s) grande(s) demais, ' + (meta.limite || 0) + ' trecho(s) acima do limite de 8 por commit e ' + (meta.arquivosGrandes || 0) + ' arquivo(s) com mais de 80 mil caracteres.' : '';
$input.all().forEach((r, i) => {
  const info = base[i].json;
  const rotulo = info.path + ' (linhas ' + (info.ini + 1) + ' a ' + (info.fim + 1) + ')';
  const ch0 = (((r.json || {}).choices || [])[0] || {});
  const txt = String((ch0.message || {}).content || '');
  const cortou = ch0.finish_reason === 'length';
  const ver = /VEREDITO:\s*(REFATORAR|OK)/i.exec(txt);
  tally.analisados++;
  if (!ver) { rej(rotulo, cortou ? 'a resposta do modelo foi cortada pelo limite de tamanho antes do veredito' : (txt.trim() ? 'a resposta não trouxe a linha VEREDITO no formato pedido' : 'o modelo não respondeu (vazio ou erro de conexão)')); return; }
  if (ver[1].toUpperCase() !== 'REFATORAR') { tally.ok++; return; }
  const m = /<<<ARQUIVO>>>\r?\n([\s\S]*?)\r?\n?<<<FIM_ARQUIVO>>>/.exec(txt);
  if (!m) { rej(rotulo, cortou ? 'o modelo pediu refatoração, mas o trecho corrigido veio cortado pelo limite de tamanho' : 'o modelo pediu refatoração, mas não entregou o trecho corrigido entre as marcas combinadas'); return; }
  let novo = m[1].replace(/^\s*```[A-Za-z0-9+#.-]*\r?\n/, '').replace(/\r?\n```\s*$/, '');
  if (info.texto.endsWith('\n') && !novo.endsWith('\n')) novo += '\n';
  if (novo.trim() === info.texto.trim()) { tally.ok++; return; }
  const razao = novo.length / info.texto.length;
  if (razao < 0.5 || razao > 1.8) { rej(rotulo, 'o trecho corrigido ficou com ' + Math.round(razao * 100) + '% do tamanho original (aceito entre 50% e 180%)'); return; }
  const A = new Set(info.texto.split('\n'));
  const B = novo.split('\n');
  const novas = B.filter(l => !A.has(l)).length / Math.max(B.length, 1);
  if (novas > 0.6) { rej(rotulo, Math.round(novas * 100) + '% das linhas são novas ou reescritas (aceito até 60%)'); return; }
  if (balanceado(info.texto) && !balanceado(novo)) { rej(rotulo, 'o código corrigido ficou com parênteses, colchetes ou chaves desbalanceados'); return; }
  const achados = parseAchados(txt);
  if (achados.length === 0) { const antes = txt.split('<<<ARQUIVO>>>')[0].replace(/\s+/g, ' ').trim().slice(0, 220); rej(rotulo, 'veio um trecho corrigido sem nenhum achado no formato pedido. O modelo escreveu: "' + antes + '"'); return; }
  const g = porArquivo[info.path] || (porArquivo[info.path] = { path: info.path, original: info.original, shaBlob: info.shaBlob, trechos: [], achados: [] });
  g.trechos.push({ ini: info.ini, fim: info.fim, novo });
  achados.forEach(a => g.achados.push(a));
});
Object.values(porArquivo).forEach(g => {
  const linhasArq = g.original.split('\n');
  g.trechos.sort((x, y) => y.ini - x.ini).forEach(t => linhasArq.splice(t.ini, t.fim - t.ini + 1, ...t.novo.split('\n')));
  const novoArq = linhasArq.join('\n');
  if (balanceado(g.original) && !balanceado(novoArq)) { rej(g.path, 'depois de juntar os trechos corrigidos, o arquivo ficou com parênteses, colchetes ou chaves desbalanceados'); return; }
  arquivos.push({ path: g.path, novo: novoArq, shaBlob: g.shaBlob });
  const linhas = ['### Arquivo `' + g.path + '` (' + g.trechos.length + ' trecho(s) alterado(s))', ''];
  g.achados.forEach((a, n) => {
    const cat = sem(a.CATEGORIA).replace(/[^a-z]/g, '');
    if (contagem[cat] !== undefined) contagem[cat]++;
    linhas.push('#### ' + (n + 1) + '. [' + (SEV[sem(a.SEVERIDADE)] || 'MÉDIA') + '] ' + (CAT[cat] || 'Geral') + ': ' + a.PROBLEMA);
    if (a.LINHAS) linhas.push('Linhas: ' + a.LINHAS);
    linhas.push('', '**Por que isso importa:** ' + (a.POR_QUE_IMPORTA || ''), '', '**O que foi alterado:** ' + (a.CORRECAO || ''), '');
  });
  secoes.push(linhas.join('\n'));
});
if (arquivos.length === 0) {
  let motivo = 'Commit ' + v.sha.slice(0, 7) + ' (' + v.repo + ', branch ' + v.branch + '): ' + tally.analisados + ' trecho(s) analisado(s). ';
  let titulo = 'GitOps: nada a refatorar';
  if (tally.descartados === 0) motivo += 'Nada a refatorar.';
  else {
    titulo = 'GitOps: nenhuma mudança aceita';
    motivo += tally.ok + ' sem problemas; ' + tally.descartados + ' descartado(s) por segurança. ' + descartes.join(' | ');
  }
  return [{ json: { vazio: true, titulo, motivo: motivo + notaOmitidos } }];
}
const ts = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
const corpo = [
  '## Revisão automática do commit `' + v.sha.slice(0, 7) + '`',
  '',
  'Este rascunho de Pull Request foi aberto automaticamente pelo Heimdall-ai (modelo deepseek-coder-v2:16b) depois de um push na branch `' + v.branch + '`. O código alterado no commit foi analisado sob três óticas: segurança, performance e arquitetura.',
  '',
  '**Revise com atenção antes de aceitar.** Um modelo local pode errar, e a refatoração não foi executada nem testada.',
  '',
  '### Resumo',
  '- Segurança: ' + contagem.seguranca + ' achado(s)',
  '- Performance e eficiência: ' + contagem.performance + ' achado(s)',
  '- Arquitetura e boas práticas: ' + contagem.arquitetura + ' achado(s)',
  '- Arquivos alterados: ' + arquivos.length,
  '- Trechos analisados: ' + tally.analisados + (notaOmitidos ? ' (' + notaOmitidos.trim() + ')' : ''),
  '',
].concat(secoes).concat([
  '### Como validar',
  '- Rode os testes do projeto e confira se o comportamento visível não mudou.',
  '- Compare cada arquivo com a versão original pela aba de diferenças deste Pull Request.',
  '- Se algum achado não fizer sentido, descarte o arquivo ou feche este rascunho. Nada foi alterado na branch `' + v.branch + '`.',
]).join('\n');
const nomes = arquivos.map(a => a.path.split('/').pop()).slice(0, 3).join(', ');
return [{ json: { vazio: false, repo: v.repo, base: v.branch, sha: v.sha, branch: 'fix/refactor-auto-' + ts, arquivos,
  titulo: ('Refatoração automática (rascunho): ' + nomes).slice(0, 100), corpo } }];

const c = $('Consolidar').first().json;
return c.arquivos.map(a => ({ json: {
  url: 'https://api.github.com/repos/' + c.repo + '/contents/' + a.path.split('/').map(encodeURIComponent).join('/'),
  mensagem: 'refactor(auto): ' + a.path + ' (Heimdall-ai)',
  conteudo: Buffer.from(a.novo, 'utf8').toString('base64'),
  sha: a.shaBlob,
  branch: c.branch,
